export declare function loadAttentionLogs(teamId: string): {
    topicLogs: Map<string, number>;
    decisionLogs: Map<string, number>;
    interactionCounts: {
        ops: number;
        innovation: number;
    };
    agentConsumption: Map<string, number>;
};
export declare function saveIdentityData(teamId: string, sentences: string[]): void;
export declare function loadIdentityData(teamId: string): string[];
export declare function saveSelfAssessment(record: SelfAssessmentRecord): void;
export declare function loadSelfAssessments(teamId: string): SelfAssessmentRecord[];
export declare function saveFinancialBaselineToDb(teamId: string, baseline: FinancialBaseline): void;
export declare function loadFinancialBaselineFromDb(teamId: string): FinancialBaseline | null;
export declare function loadAllFinancialBaselines(): Map<string, FinancialBaseline>;
